            for _ in range(5):
                if out and out[-1] in ",;:|":
                    out = out[:-1].strip()
                else:
                    break
            if out.endswith("."):
                lastw = out.split(" ")[-1][:-1]
                if lastw.lower() not in ABBREV and len(lastw) > 1:
                    out = out[:-1].strip()
            out = out.strip(" -–—|")
