        ACRONYMS = {"PAC", "PACS", "SUPERPAC", "USA", "US", "GOP", "NRA", "LLC", "INC",
                    "AFL", "CIO", "DNC", "RNC", "NRSC", "NRCC", "DSCC", "DCCC", "JR",
                    "SR", "II", "III", "IV", "PC", "DC", "SCF", "NY", "CA", "TX"}
