            """Collapse a name printed twice back-to-back, ignoring spacing differences.

            'Rosenfor Nevada Rosen for Nevada' -> the better-spaced half, 'Rosen for Nevada'.
            """
            n = len(words)
            for k in range(1, n):
                first, second = words[:k], words[k:]
                a, b = letters_of(first), letters_of(second)
                if a and a == b:
                    return second if len(second) > len(first) else first
            return words

